using System.Text;
using System.Text.Json;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Evals;

public sealed record UsoEval(int Entrada, int Salida);

public sealed record ArtefactoCorrida(
    string Pregunta,
    UsuarioEval Usuario,
    int Corrida,
    IReadOnlyList<string> TextosCrudos,
    IReadOnlyList<string> SeccionesEntregadas,
    bool ConResumen,
    bool ConPrelectura,
    IReadOnlyList<UsoEval> Usage,
    string? Respuesta,
    IReadOnlyList<string> Citas);

public sealed class GrabadorLlm(IClienteLlm interno) : IClienteLlm
{
    private readonly Lock _candado = new();
    private readonly List<(SolicitudLlm Solicitud, RespuestaLlm Respuesta)> _llamadas = [];

    public IReadOnlyList<(SolicitudLlm Solicitud, RespuestaLlm Respuesta)> Llamadas
    {
        get
        {
            lock (_candado)
            {
                return [.. _llamadas];
            }
        }
    }

    public async Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
    {
        var respuesta = await interno.CompletarAsync(solicitud, cancellationToken);
        lock (_candado)
        {
            _llamadas.Add((solicitud, respuesta));
        }

        return respuesta;
    }
}

public static class ArtefactosFaseV
{
    private const string FuenteDelResumen = Textos.FuenteResumenPropio;
    private const string PrefijoDeDatos = "Datos del";

    private static readonly JsonSerializerOptions OpcionesDeEscritura = new(Json.Opciones) { WriteIndented = true, Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    public static string Guardar(string carpeta, string nombre, ArtefactoCorrida artefacto, string? llave)
    {
        Directory.CreateDirectory(carpeta);
        var contenido = JsonSerializer.Serialize(artefacto, OpcionesDeEscritura);
        var ruta = Path.Combine(carpeta, $"{nombre}.json");
        File.WriteAllText(ruta, SinLaLlave(contenido, llave), Encoding.UTF8);
        return ruta;
    }

    public static ArtefactoCorrida Armar(CasoEval caso, int corrida, GrabadorLlm? grabador, SalidaEval? salida)
    {
        var llamadas = grabador?.Llamadas ?? [];
        var bloques = BloquesDeLaPrimeraLlamada(llamadas);
        return new ArtefactoCorrida(
            caso.Pregunta,
            caso.Usuario,
            corrida,
            [.. llamadas.Select(l => l.Respuesta.Texto ?? string.Empty)],
            [.. bloques.Select(b => b.Fuente).Where(EsSeccionDeDocumento)],
            bloques.Any(b => b.Fuente == FuenteDelResumen),
            bloques.Any(b => b.Fuente.StartsWith(Textos.DocumentoDatosPrograma, StringComparison.Ordinal)),
            [.. llamadas.Select(l => new UsoEval(l.Respuesta.Uso.Entrada, l.Respuesta.Uso.Salida))],
            salida?.Respuesta,
            CitasDe(salida));
    }

    private static IReadOnlyList<BloqueDelimitado> BloquesDeLaPrimeraLlamada(IReadOnlyList<(SolicitudLlm Solicitud, RespuestaLlm Respuesta)> llamadas) =>
        llamadas.Count == 0 ? [] : GuionesLlm.Bloques(llamadas[0].Solicitud);

    private static string[] CitasDe(SalidaEval? salida) =>
        [.. (salida?.Citas ?? []).Select(c => c.Texto)];

    private static bool EsSeccionDeDocumento(string fuente) =>
        fuente != FuenteDelResumen && !fuente.StartsWith(PrefijoDeDatos, StringComparison.Ordinal);

    private static string SinLaLlave(string contenido, string? llave) =>
        string.IsNullOrWhiteSpace(llave) ? contenido : contenido.Replace(llave, "[LLAVE]", StringComparison.Ordinal);
}
using System.Diagnostics;
using TutorFlow.Api.Tests;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Evals;

public sealed class EjecutorFaseV(bool offline, string carpeta, string? llave) : IEjecutor
{
    private readonly Dictionary<string, int> _corridas = [];

    public async Task<Ejecucion?> EjecutarAsync(CasoEval caso, CancellationToken cancellationToken)
    {
        if (caso.RequiereLlm && offline && caso.Offline is null)
        {
            return null;
        }

        var corrida = _corridas[caso.Id] = _corridas.GetValueOrDefault(caso.Id) + 1;
        GrabadorLlm? grabador = null;
        using var fabrica = Fabricar(caso, g => grabador = g);
        var reloj = Stopwatch.StartNew();
        var respuesta = await fabrica.EnviarAsync(HttpMethod.Post, Cuerpos.Ruta, Cuerpos.De(caso));
        reloj.Stop();
        var artefacto = ArtefactosFaseV.Armar(caso, corrida, grabador, Json.LeerSalida(respuesta.Texto));
        ArtefactosFaseV.Guardar(carpeta, $"{TablaFaseV.Pregunta(caso)}-{caso.Id}-corrida-{corrida}", artefacto, llave);
        return new Ejecucion(respuesta.Estado, respuesta.Texto, reloj.Elapsed.TotalMilliseconds);
    }

    private FabricaApi Fabricar(CasoEval caso, Action<GrabadorLlm> registrar)
    {
        IClienteLlm Grabar(IClienteLlm interno)
        {
            var grabador = new GrabadorLlm(interno);
            registrar(grabador);
            return grabador;
        }

        return offline
            ? new FabricaApi(llm: EjecutorEnProceso.LlmPara(caso.Offline), conocimientoReal: true, configuracion: FabricaApi.Precios("0.10", "0.50"), envolverLlm: Grabar)
            : new FabricaApi(reemplazarLlm: false, conocimientoReal: true, envolverLlm: Grabar);
    }
}
using System.Diagnostics;
using System.Text;
using System.Text.Json;
using TutorFlow.Api.Tests;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Evals;

public interface IEjecutor
{
    Task<Ejecucion?> EjecutarAsync(CasoEval caso, CancellationToken cancellationToken);
}

public static class Cuerpos
{
    public const string Ruta = "/api/asistente/preguntar";

    public static string De(CasoEval caso) =>
        JsonSerializer.Serialize(new { pregunta = caso.Pregunta, usuario = new { rol = caso.Usuario.Rol, id = caso.Usuario.Id } });
}

public sealed class EjecutorHttp : IEjecutor
{
    private readonly HttpClient _cliente;
    private readonly int _pausaMs;

    public EjecutorHttp(HttpClient cliente, int pausaMs)
    {
        _cliente = cliente;
        _pausaMs = pausaMs;
    }

    public async Task<Ejecucion?> EjecutarAsync(CasoEval caso, CancellationToken cancellationToken)
    {
        if (caso.SoloOffline)
        {
            return null;
        }

        await Task.Delay(_pausaMs, cancellationToken);
        var reloj = Stopwatch.StartNew();
        using var contenido = new StringContent(Cuerpos.De(caso), Encoding.UTF8, "application/json");
        using var respuesta = await _cliente.PostAsync(Cuerpos.Ruta, contenido, cancellationToken);
        var texto = await respuesta.Content.ReadAsStringAsync(cancellationToken);
        reloj.Stop();
        return new Ejecucion((int)respuesta.StatusCode, texto, reloj.Elapsed.TotalMilliseconds);
    }
