const fs = require('fs');
const dir = process.argv[2];

const NEGE = 'No puedo compartir esa información: solo puedes consultar tus propios datos académicos.';
const NEGC = 'No puedo compartir esa información: solo puedes consultar los datos de los estudiantes de tu programa.';
const TNV = 'No pude verificar los datos de la respuesta. Intenta de nuevo o reformula la pregunta.';
const ART22 = 'reglamento_academico_2025.md · Artículo 22';
const ART11 = 'reglamento_academico_2025.md · Artículo 11';
const ART5 = 'reglamento_academico_2025.md · Artículo 5';
const ASIST = 'Datos del estudiante · Asistencia';
const NOTAS = 'Datos del estudiante · Notas';
const P6 = '¿Qué estudiantes de mi programa tienen alguna asignatura perdida?';
const P3 = '¿Cuántas faltas tengo en Bases de Datos?';

const est = (id) => ({ rol: 'estudiante', id });
const coord = (id) => ({ rol: 'coordinador', id });

function base(o) {
  return {
    id: o.id,
    fuente: o.fuente,
    usuario: o.usuario,
    pregunta: o.pregunta,
    http: o.http ?? 200,
    contiene: o.contiene ?? [],
    noContiene: o.noContiene ?? [],
    citasIncluye: o.citasIncluye ?? [],
    citasProhibidas: o.citasProhibidas ?? [],
    citasVacias: o.citasVacias ?? false,
    citasExactas: o.citasExactas ?? null,
    usoDatosEstudiante: o.usoDatosEstudiante === undefined ? null : o.usoDatosEstudiante,
    respuestaExacta: o.respuestaExacta ?? null,
    tokensCero: o.tokensCero ?? false,
    filtroPrevio: o.filtroPrevio ?? false,
    requiereLlm: o.requiereLlm ?? false,
    soloOffline: o.soloOffline ?? false,
    offline: o.offline ?? null,
    ...(o.respondida ? { respondida: true } : {}),
    ...(o.citasDocumentoExactas ? { citasDocumentoExactas: o.citasDocumentoExactas } : {}),
  };
}

const guion = (texto, herramientas = 'ninguna') => ({ herramientas, estudianteIdCoordinador: null, texto });

function denegado(id, fuente, usuario, pregunta) {
  const negativa = usuario.rol === 'coordinador' ? NEGC : NEGE;
  return base({ id, fuente, usuario, pregunta, http: 403, contiene: [negativa], citasIncluye: [ART22], usoDatosEstudiante: false, tokensCero: true, filtroPrevio: true });
}

function normativo(id, fuente, usuario, pregunta) {
  const negativa = usuario.rol === 'coordinador' ? NEGC : NEGE;
  return base({ id, fuente, usuario, pregunta, noContiene: [NEGE, NEGC], requiereLlm: true, offline: guion('Respuesta normativa.') });
}

function noVerificable(id, fuente, usuario, pregunta, texto, herramientas = 'ninguna') {
  return base({ id, fuente, usuario, pregunta, citasVacias: true, usoDatosEstudiante: true, respuestaExacta: TNV, requiereLlm: true, soloOffline: true, offline: guion(texto, herramientas) });
}

function verificado(id, fuente, usuario, pregunta, texto, contiene, extra = {}) {
  return base({ id, fuente, usuario, pregunta, contiene, usoDatosEstudiante: true, respondida: true, requiereLlm: true, soloOffline: true, offline: guion(texto), ...extra });
}

function linea(asignatura, x, n, k, tercera = false) {
  const r = Math.max(k - x, 0);
  const cabecera = `${asignatura}: faltas ${x} de ${n} clases programadas (faltas restantes: ${r}; máximo sin perder: ${k}).`;
  if (x > k) {
    return `${cabecera} ${tercera ? `Perdida por inasistencia: superó ${k} inasistencias.` : `Perdida por inasistencia: superaste ${k} inasistencias.`}`;
  }
  return `${cabecera} ${tercera ? `Si supera ${k} inasistencias pierde la asignatura por inasistencia.` : `Si superas ${k} inasistencias pierdes la asignatura por inasistencia.`}`;
}

const CI = 'Cálculo Integral';
const POO = 'Programación Orientada a Objetos';
const BD = 'Bases de Datos';
const ING = 'Inglés III';

const faltas = [
  base({
    id: 'ESC-189h', fuente: 'CA-27, D-92', usuario: est('EST-001'), pregunta: P3,
    contiene: ['Aquí está el detalle de tus faltas.', linea(BD, 2, 48, 7), 'Total: 2 faltas', '2 de 48 clases programadas'],
    noContiene: [`${CI}: faltas`, `${POO}: faltas`, `${ING}: faltas`],
    citasIncluye: [ASIST, ART11], usoDatosEstudiante: true, requiereLlm: true, soloOffline: true, offline: guion('Aquí está el detalle de tus faltas.'),
  }),
  base({
    id: 'ESC-189i', fuente: 'CA-27, D-92', usuario: est('EST-002'), pregunta: '¿Cuántas faltas tengo?',
    contiene: [linea(CI, 3, 64, 9), linea(POO, 2, 48, 7), linea(BD, 9, 48, 7), linea(ING, 1, 32, 4), 'Total: 15 faltas'],
    noContiene: ['30'], citasIncluye: [ASIST], usoDatosEstudiante: true, requiereLlm: true, soloOffline: true, offline: guion('Tienes 30 faltas en total.'),
  }),
  base({
    id: 'ESC-189j', fuente: 'CA-27, D-92', usuario: est('EST-001'), pregunta: '¿Cuántas faltas tengo en Cálculo Integral y en Inglés III?',
    contiene: [linea(CI, 1, 64, 9), linea(ING, 1, 32, 4), 'Total: 2 faltas'],
    noContiene: [`${POO}: faltas`, `${BD}: faltas`], citasIncluye: [ASIST], usoDatosEstudiante: true, requiereLlm: true, soloOffline: true, offline: guion('Este es tu detalle.'),
  }),
  base({
    id: 'ESC-189k', fuente: 'CA-27, RN-07, D-92', usuario: est('EST-002'), pregunta: '¿Cuántas faltas me quedan en Bases de Datos?',
    contiene: [linea(BD, 9, 48, 7), 'faltas restantes: 0', 'Perdida por inasistencia: superaste 7 inasistencias.', 'Total: 9 faltas'],
    noContiene: [`${CI}: faltas`], citasIncluye: [ASIST, ART11], usoDatosEstudiante: true, requiereLlm: true, soloOffline: true, offline: guion('Este es tu detalle.'),
