function base(o) {
  return {
    id: o.id,
    fuente: o.fuente,
    usuario: o.usuario,
    pregunta: o.pregunta,
    http: o.http ?? 200,
    contiene: o.contiene ?? [],
    noContiene: o.noContiene ?? [],
    citasIncluye: o.citasIncluye ?? [],
    citasProhibidas: o.citasProhibidas ?? [],
    citasVacias: o.citasVacias ?? false,
    citasExactas: o.citasExactas ?? null,
    usoDatosEstudiante: o.usoDatosEstudiante === undefined ? null : o.usoDatosEstudiante,
    respuestaExacta: o.respuestaExacta ?? null,
    tokensCero: o.tokensCero ?? false,
    filtroPrevio: o.filtroPrevio ?? false,
    requiereLlm: o.requiereLlm ?? false,
    soloOffline: o.soloOffline ?? false,
    offline: o.offline ?? null,
    ...(o.respondida ? { respondida: true } : {}),
    ...(o.citasDocumentoExactas ? { citasDocumentoExactas: o.citasDocumentoExactas } : {}),
  };
}

const guion = (texto, herramientas = 'ninguna') => ({ herramientas, estudianteIdCoordinador: null, texto });

function denegado(id, fuente, usuario, pregunta) {
  const negativa = usuario.rol === 'coordinador' ? NEGC : NEGE;
  return base({ id, fuente, usuario, pregunta, http: 403, contiene: [negativa], citasIncluye: [ART22], usoDatosEstudiante: false, tokensCero: true, filtroPrevio: true });
}

function normativo(id, fuente, usuario, pregunta) {
  const negativa = usuario.rol === 'coordinador' ? NEGC : NEGE;
  return base({ id, fuente, usuario, pregunta, noContiene: [NEGE, NEGC], requiereLlm: true, offline: guion('Respuesta normativa.') });
}

function noVerificable(id, fuente, usuario, pregunta, texto, herramientas = 'ninguna') {
  return base({ id, fuente, usuario, pregunta, citasVacias: true, usoDatosEstudiante: true, respuestaExacta: TNV, requiereLlm: true, soloOffline: true, offline: guion(texto, herramientas) });
}

function verificado(id, fuente, usuario, pregunta, texto, contiene, extra = {}) {
  return base({ id, fuente, usuario, pregunta, contiene, usoDatosEstudiante: true, respondida: true, requiereLlm: true, soloOffline: true, offline: guion(texto), ...extra });
}

function linea(asignatura, x, n, k, tercera = false) {
  const r = Math.max(k - x, 0);
  const cabecera = `${asignatura}: faltas ${x} de ${n} clases programadas (faltas restantes: ${r}; máximo sin perder: ${k}).`;
  if (x > k) {
    return `${cabecera} ${tercera ? `Perdida por inasistencia: superó ${k} inasistencias.` : `Perdida por inasistencia: superaste ${k} inasistencias.`}`;
  }
  return `${cabecera} ${tercera ? `Si supera ${k} inasistencias pierde la asignatura por inasistencia.` : `Si superas ${k} inasistencias pierdes la asignatura por inasistencia.`}`;
}

