function escribir(archivo, nuevos) {
  fs.writeFileSync(`${dir}/${archivo}`, JSON.stringify(nuevos, null, 2) + '\n');
}

function anexar(archivo, nuevos) {
  const ruta = `${dir}/${archivo}`;
  const actuales = JSON.parse(fs.readFileSync(ruta, 'utf8'));
  const ids = new Set(actuales.map((c) => c.id));
  for (const c of nuevos) {
    if (ids.has(c.id)) throw new Error(`duplicado ${c.id}`);
  }
  fs.writeFileSync(ruta, JSON.stringify([...actuales, ...nuevos], null, 2) + '\n');
}

function editar(archivo, id, cambio) {
  const ruta = `${dir}/${archivo}`;
  const casos = JSON.parse(fs.readFileSync(ruta, 'utf8'));
  const caso = casos.find((c) => c.id === id);
  if (!caso) throw new Error(`falta ${id}`);
  cambio(caso);
  fs.writeFileSync(ruta, JSON.stringify(casos, null, 2) + '\n');
}

