}

function linea(asignatura, x, n, k, tercera = false) {
  const r = Math.max(k - x, 0);
  const cabecera = `${asignatura}: faltas ${x} de ${n} clases programadas (faltas restantes: ${r}; máximo sin perder: ${k}).`;
  if (x > k) {
