const fs = require('fs');
const dir = process.argv[2];
const carpeta = `${dir}/05 permisos y roles`;

const plantilla403 = fs.readFileSync(`${carpeta}/ESC-037 a que puede ver mi coordinador.request.yaml`, 'utf8');
const plantilla200 = fs.readFileSync(`${carpeta}/ESC-187 d mi nota mas alta.request.yaml`, 'utf8');

const preguntaOriginal403 = '¿Qué puede ver mi coordinador?';
const preguntaOriginal200 = '¿Cuál es mi nota más alta?';

function json(texto) {
  return JSON.stringify(texto).slice(1, -1);
}

function generar(plantilla, etiquetaOriginal, preguntaOriginal, etiqueta, pregunta, orden, esNormativa) {
  let t = plantilla.split(etiquetaOriginal).join(etiqueta);
  t = t.replace(/^order: \d+/m, `order: ${orden}`);
  t = t.replace(`"pregunta": "${json(preguntaOriginal)}"`, `"pregunta": "${json(pregunta)}"`);
  if (esNormativa) {
    t = t.replace(/\n\s+pm\.expect\(pm\.response\.json\(\)\.tokens\)\.to\.be\.above\(0\);/, '');
  }
  if (!t.includes(json(pregunta))) throw new Error(`pregunta no insertada: ${etiqueta}`);
  return t;
}

const ya = new Set(fs.readdirSync(carpeta));
let orden = 79000;

function escribir(etiqueta, slug, contenido) {
  const nombre = `${etiqueta} ${slug}.request.yaml`;
  if (ya.has(nombre)) throw new Error(`existe ${nombre}`);
  fs.writeFileSync(`${carpeta}/${nombre}`, contenido);
  orden += 1000;
}

function denegada(etiqueta, slug, pregunta) {
  escribir(etiqueta, slug, generar(plantilla403, 'ESC-037 a', preguntaOriginal403, etiqueta, pregunta, orden, false));
}

function normativa(etiqueta, slug, pregunta) {
  escribir(etiqueta, slug, generar(plantilla200, 'ESC-187 d', preguntaOriginal200, etiqueta, pregunta, orden, true));
}

